"""Integrity checks of the confirmation runs (writes gm_integrity.md): expected seeds, splits, learners x budgets x draws present exactly once, no dev seeds inside, graph-quality records present for every dose learner,
frozen learner list equals the PREREGISTRATION_GM1 list, seed blocks disjoint from other sessions' ranges.   python3 gm_integrity.py"""
import json, re, sys
from pathlib import Path
HERE = Path(__file__).resolve().parent; RES = HERE.parents[1] / "new_directions" / "results" / "gm"; sys.path.insert(0, str(HERE.parents[1] / "new_directions"))
import nd_core as core
L = "aw8_all,lap3_k10,gm_lap3_n0,gm_lap3_n0.5,gm_lap3_n1,gm_lap3_n2,gm_lap3_n3,gm_lap10_n0,gm_lap10_n0.5,gm_lap10_n1,gm_lap10_n2,gm_lap10_n3,gm_lap10_n0_shuf,gmc_t_no_rt13,gmc_t_no_rt13_shuf,gmc_t_no_rt13_n3,gm_noise10".split(",")
prereg = (HERE / "PREREGISTRATION_GM1.md").read_text(); lines = []; ok = True
def check(cond, msg):
    global ok; ok &= bool(cond); lines.append(f"- {'PASS' if cond else 'FAIL'}: {msg}")
for name, seeds in (("confirm1", core.GM_CONFIRM1), ("confirm2", core.GM_CONFIRM2)):
    d = RES / name; files = sorted(d.glob("seed*_*.json")); got = {(int(re.search(r"seed(\d+)_([AB])", f.name).group(1)), re.search(r"_([AB])\.json", f.name).group(1)) for f in files}
    check(got == {(s, sp) for s in seeds for sp in "AB"}, f"{name}: exactly the {len(seeds)} seeds {seeds[0]}-{seeds[-1]} x splits A,B ({len(files)} files)")
    bad = []
    for f in files:
        recs = json.loads(f.read_text()); key = [(r["budget"], r["draw"], r["learner"]) for r in recs]
        if len(key) != len(set(key)) or set(key) != {(b, dr, l) for b in core.BUDGETS for dr in range(3) for l in L}: bad.append(f.name)
    check(not bad, f"{name}: every file has each of the {len(L)} frozen learners x 4 budgets x 3 draws exactly once" + (f" (bad: {bad[:3]})" if bad else ""))
    check(all(r["seed"] in seeds for f in files for r in json.loads(f.read_text())), f"{name}: all records carry seeds of the block")
    qdir = RES / "quality"; miss = [(s, sp, n) for s in seeds for sp in "AB" for n in L if n.startswith("gm_lap") and not (qdir / f"seed{s}_{sp}.json").exists() or n.startswith("gm_lap") and n not in json.loads((qdir / f"seed{s}_{sp}.json").read_text())]
    check(not miss, f"{name}: graph-quality record for every dose learner, seed and split" + (f" (missing {len(miss)})" if miss else ""))
check(all(l in prereg for l in ("gmc_t_no_rt13", "gm_lap10_n0", "gm_noise10", "gmc_t_no_rt13_shuf", "gm_lap10_n0_shuf", "gmc_t_no_rt13_n3")), "frozen learners are all named in PREREGISTRATION_GM1.md")
check(set(core.GM_DEV_SEEDS).isdisjoint(core.GM_CONFIRM1) and set(core.GM_DEV_SEEDS).isdisjoint(core.GM_CONFIRM2) and set(core.GM_CONFIRM1).isdisjoint(core.GM_CONFIRM2), "development / confirmation 1 / confirmation 2 seed blocks are disjoint")
check(core.GM_SEEDS_ALL.isdisjoint(set(range(7000, 7336))) and core.GM_SEEDS_ALL.isdisjoint(set(range(8200, 8600))), "seed blocks disjoint from 7000-7335 (graph-learner) and 8200-8599 (parallel sessions)")
dev = [d.name for d in RES.iterdir() if d.is_dir() and d.name.startswith("dev")]; seeds_dev = {int(re.search(r"seed(\d+)", f.name).group(1)) for d in dev for f in (RES / d).glob("seed*.json")}
check(seeds_dev <= set(core.GM_DEV_SEEDS), f"all development cells use development seeds only ({len(seeds_dev)} distinct seeds)")
(HERE / "gm_integrity.md").write_text("# Integrity checks of the graph-mechanism runs (generated by gm_integrity.py)\n\n" + "\n".join(lines) + f"\n\nOverall: {'ALL PASS' if ok else 'SOME FAILED'}\n"); print("\n".join(lines)); print("ALL PASS" if ok else "SOME FAILED")
